import unittest
import treasure_hunt

class TestTreasureHunt(unittest.TestCase):
    def test_initial_location(self):
        self.assertEqual(treasure_hunt.current_location, "Beach")

    def test_move_to_temple(self):
        treasure_hunt.move_to("Temple")
        self.assertEqual(treasure_hunt.current_location, "Temple")

    def test_move_to_chest(self):
        treasure_hunt.move_to("Chest")
        self.assertEqual(treasure_hunt.current_location, "Chest")

    def test_move_to_non_existent_location(self):
        with self.assertRaises(KeyError):
            treasure_hunt.move_to("Mountain")

    def test_get_score(self):
        self.assertEqual(treasure_hunt.get_score(), 0)
        treasure_hunt.current_location = "Chest"
        self.assertEqual(treasure_hunt.get_score(), 1000)

    def test_game_over(self):
        treasure_hunt.current_location = "Chest"
        self.assertTrue(treasure_hunt.game_over())

if __name__ == "__main__":
    unittest

